<?php $gallery=json_decode((string)($product['gallery']??'[]'),true)?:[];if($product['image']){$gallery=array_values(array_filter($gallery,fn($image)=>$image!==$product['image']));array_unshift($gallery,$product['image']);}$price=$product['promotional_price']!==null?(float)$product['promotional_price']:(float)$product['price'];$digital=($product['product_type']??'physical')==='digital';$stockLabels=['in_stock'=>'EN STOCK','on_order'=>'SUR COMMANDE','out_of_stock'=>'RUPTURE DE STOCK']; ?>
<section class="product-detail"><div class="product-gallery"><div class="product-main-photo steel"><?php if($gallery): ?><img id="productMainImage" src="<?= htmlspecialchars($gallery[0]) ?>" alt="<?= htmlspecialchars($product['name']) ?>"><?php else: ?><span>IFMAP<br><?= $digital?'ÉDITION':'EQUIPMENT' ?></span><b>│────────│</b><?php endif ?></div><?php if(count($gallery)>1): ?><div class="thumbs"><?php foreach($gallery as $image): ?><button type="button" data-product-image="<?= htmlspecialchars($image) ?>"><img src="<?= htmlspecialchars($image) ?>" alt=""></button><?php endforeach ?></div><?php endif ?></div><div class="product-info"><div class="product-topline"><a class="breadcrumbs" href="/boutique">Boutique / <?= htmlspecialchars($product['category']??'Équipements') ?></a><?php $shareTitle=(string)$product['name'].' — IFMAP';$shareText='Découvrez '.(string)$product['name'].' sur IFMAP.';$shareCompact=true;require __DIR__.'/../partials/share-menu.php'; ?></div><span class="stock in">● <?= $digital?'LIVRE NUMÉRIQUE · ACCÈS IMMÉDIAT':$stockLabels[$product['stock_status']] ?><?= !$digital&&$product['lead_time']?' · '.htmlspecialchars(strtoupper($product['lead_time'])):'' ?></span><h1><?= htmlspecialchars($product['name']) ?></h1><p class="product-ref">Réf. <?= htmlspecialchars($product['reference']) ?></p><div class="product-description"><?= nl2br(htmlspecialchars($product['description']?:'Produit professionnel sélectionné par IFMAP.')) ?></div><?php if($product['promotional_price']!==null): ?><div class="promo-pill">OFFRE PROMOTIONNELLE</div><strong class="product-price"><?= number_format($price,0,',',' ') ?> FCFA <s><?= number_format((float)$product['price'],0,',',' ') ?> FCFA</s></strong><?php else: ?><strong class="product-price"><?= $product['price']!==null?number_format($price,0,',',' ').' FCFA':'Prix sur demande' ?></strong><?php endif ?><?php if(($digital||$product['stock_status']!=='out_of_stock')&&$product['price']!==null): ?><form class="add-form" method="post" action="/panier/ajouter"><input type="hidden" name="type" value="product"><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><?php if(!$digital): ?><label>Quantité <span><button type="button" data-qty="-1">−</button><input name="quantity" value="1" min="1" max="<?= max(1,(int)$product['stock_quantity']) ?>" type="number"><button type="button" data-qty="1">+</button></span></label><?php endif ?><button class="site-btn gold"><?= $digital?'Acheter et télécharger':'Ajouter au panier' ?> →</button></form><?php endif ?><div class="delivery-notes"><?php if($digital): ?><span>↓ <b>Téléchargement immédiat</b><small>Après validation du paiement</small></span><span>⌁ <b>Lien personnel sécurisé</b><small>Actif 30 jours · <?= (int)$product['download_limit'] ?> accès</small></span><?php else: ?><span>⌂ <b>Retrait gratuit</b><small>Koumassi ou Yopougon</small></span><span>▣ <b>Livraison à Abidjan</b><small>Suivi jusqu’à la réception</small></span><?php endif ?></div></div></section>
<?php if($related): ?><section class="related-products"><div class="site-section-head"><p class="site-kicker">VOUS AIMEREZ AUSSI</p><h2>Produits de la même catégorie</h2></div><div class="product-grid"><?php foreach($related as $item): ?><article class="product-card"><a class="product-image navy" href="/boutique/<?= rawurlencode($item['slug']) ?>"><?php if($item['image']): ?><img src="<?= htmlspecialchars($item['image']) ?>" alt=""><?php else: ?><span>IFMAP EQUIPMENT</span><?php endif ?></a><div><h2><?= htmlspecialchars($item['name']) ?></h2><footer><strong><?= number_format((float)($item['promotional_price']??$item['price']),0,',',' ') ?> FCFA</strong><a href="/boutique/<?= rawurlencode($item['slug']) ?>">Voir →</a></footer></div></article><?php endforeach ?></div></section><?php endif ?>
<script>document.querySelectorAll('[data-product-image]').forEach(b=>b.addEventListener('click',()=>document.getElementById('productMainImage').src=b.dataset.productImage));</script>
